import sys

def main():
    data = sys.stdin.read().split()
    m = int(data[0])
    nxt = {}
    seconds = set()
    for i in range(m):
        a, b = data[1 + 2 * i], data[2 + 2 * i]
        nxt[a] = b
        seconds.add(b)
    head = None
    for a in nxt:
        if a not in seconds:
            head = a
            break
    out = [head]
    while out[-1] in nxt:
        out.append(nxt[out[-1]])
    print(' '.join(out))

main()

